package ru.avrescue.app;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.os.Bundle;
import android.provider.MediaStore;
import android.text.InputType;
import android.util.Base64;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.*;

public class RegisterActivity extends Activity {
 private static final int REQUEST_GALLERY=200,REQUEST_CAMERA=201,REQUEST_CAMERA_PERMISSION=202,MAX_IMAGE_SIDE=1600;
 String type,pendingKind="",registrationUploadToken=""; Uri cameraUri; LinearLayout form; TextView status; EditText name,phone,email,login,pass,company,inn,plate,capacity; Spinner vehicle; CheckBox contract;
 LinkedHashMap<String,String> docs=new LinkedHashMap<>(); LinkedHashMap<String,CheckBox> serviceChecks=new LinkedHashMap<>(); LinkedHashMap<String,Button> photoButtons=new LinkedHashMap<>(); LinkedHashMap<String,ImageView> photoPreviews=new LinkedHashMap<>();
 public void onCreate(Bundle b){super.onCreate(b);type=getIntent().getStringExtra("type");if(type==null)type="client";render();}
 EditText field(String h){EditText e=Ui.input(this,h);form.addView(e);return e;}
 public void render(){ScrollView sv=new ScrollView(this);LinearLayout page=Ui.column(this);sv.addView(page);page.addView(Ui.brand(this));page.addView(Ui.muted(this,"Найдём помощь рядом",15));form=Ui.card(this);page.addView(form);
  String title=type.equals("executor")?"Стать исполнителем":type.equals("b2b")?"B2B-партнёрам":"Регистрация клиента";form.addView(Ui.text(this,title,24,true));
  if(type.equals("b2b")){company=field("Компания");inn=field("ИНН");name=field("Контактное лицо");}else name=field(type.equals("executor")?"ФИО / название ИП":"Ваше имя");
  phone=field("Телефон");email=field(type.equals("client")?"Email":"Email / логин");if(type.equals("client"))login=field("Логин");pass=field("Пароль, минимум 6 символов");pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);form.addView(Ui.muted(this,"После регистрации подтвердите телефон кодом из SMS и почту кодом из письма.",13));
  if(type.equals("executor")){vehicle=new Spinner(this);String[] a={"Тип эвакуатора / техники","Эвакуатор — ломаная платформа","Эвакуатор — сдвижная платформа","Эвакуатор — прямая платформа","Эвакуатор — манипулятор до 3 т","Эвакуатор — манипулятор от 3 т","Эвакуатор — частичная погрузка","Грузовой эвакуатор","Мотоэвакуатор","Техпомощь / мобильный механик"};vehicle.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,a));form.addView(vehicle);plate=field("Госномер техники");capacity=field("Грузоподъёмность, т");form.addView(Ui.text(this,"Выберите выполняемые услуги",18,true));for(String service:new String[]{"Эвакуация","Техпомощь","Запуск двигателя","Замена колеса","Подвоз топлива","Вскрытие автомобиля"}){CheckBox check=new CheckBox(this);check.setText(service);check.setTextColor(Color.WHITE);check.setChecked("Эвакуация".equals(service));serviceChecks.put(service,check);form.addView(check);}form.addView(Ui.text(this,"Обязательные фото и документы",18,true));addPhoto("profile_photo","Фото водителя / селфи");addPhoto("vehicle_front","Авто — спереди");addPhoto("vehicle_rear","Авто — сзади");addPhoto("vehicle_left","Авто — левый борт");addPhoto("vehicle_right","Авто — правый борт");addPhoto("driver_license_front","Водительское — лицевая сторона");addPhoto("driver_license_back","Водительское — оборот");addPhoto("sts_front","СТС — лицевая сторона");addPhoto("sts_back","СТС — оборот");contract=new CheckBox(this);contract.setText("Я принимаю договор исполнителя AV Rescue и правила комиссии/расчётов");contract.setTextColor(Color.WHITE);form.addView(contract);}
  Button go=Ui.button(this,type.equals("executor")?"Отправить заявку":type.equals("b2b")?"Создать B2B аккаунт":"Зарегистрироваться");Button back=Ui.darkButton(this,"Уже есть аккаунт — войти");status=Ui.muted(this,"",14);form.addView(go);form.addView(back);form.addView(status);setContentView(sv);go.setOnClickListener(v->submit());back.setOnClickListener(v->finish());}
 String s(EditText e){return e==null?"":e.getText().toString().trim();}
 void addPhoto(String kind,String label){Button button=Ui.darkButton(this,"+ "+label);ImageView preview=new ImageView(this);preview.setScaleType(ImageView.ScaleType.CENTER_CROP);preview.setVisibility(android.view.View.GONE);LinearLayout.LayoutParams imageParams=new LinearLayout.LayoutParams(-1,Ui.dp(this,180));imageParams.setMargins(0,Ui.dp(this,6),0,Ui.dp(this,10));photoButtons.put(kind,button);photoPreviews.put(kind,preview);button.setOnClickListener(v->{pendingKind=kind;new AlertDialog.Builder(this).setTitle(label).setItems(new String[]{"Сделать фото","Выбрать из галереи"},(dialog,which)->{if(which==0)openCamera();else openGallery();}).setNegativeButton("Отмена",null).show();});form.addView(button);form.addView(preview,imageParams);}
 void openCamera(){if(android.os.Build.VERSION.SDK_INT>=23&&checkSelfPermission(android.Manifest.permission.CAMERA)!=getPackageManager().PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.CAMERA},REQUEST_CAMERA_PERMISSION);return;}Intent intent=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);if(intent.resolveActivity(getPackageManager())==null){status.setText("На телефоне не найдено приложение камеры");return;}try{ContentValues values=new ContentValues();values.put(MediaStore.Images.Media.DISPLAY_NAME,"AVR_"+System.currentTimeMillis()+".jpg");values.put(MediaStore.Images.Media.MIME_TYPE,"image/jpeg");if(android.os.Build.VERSION.SDK_INT>=29){values.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/AV Rescue");values.put(MediaStore.Images.Media.IS_PENDING,1);}cameraUri=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values);if(cameraUri==null)throw new IOException();intent.putExtra(MediaStore.EXTRA_OUTPUT,cameraUri);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);intent.setClipData(ClipData.newRawUri("AV Rescue photo",cameraUri));startActivityForResult(intent,REQUEST_CAMERA);}catch(Exception e){cameraUri=null;status.setText("Не удалось открыть камеру");}}
 @Override public void onRequestPermissionsResult(int requestCode,String[] permissions,int[] grantResults){super.onRequestPermissionsResult(requestCode,permissions,grantResults);if(requestCode==REQUEST_CAMERA_PERMISSION){if(grantResults.length>0&&grantResults[0]==getPackageManager().PERMISSION_GRANTED)openCamera();else status.setText("Разрешите доступ к камере, чтобы сделать фотографию");}}
 void openGallery(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("image/*");intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(intent,REQUEST_GALLERY);}catch(Exception e){status.setText("Не удалось открыть галерею");}}
 @Override public void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(resultCode!=RESULT_OK||pendingKind.isEmpty()){if(requestCode==REQUEST_CAMERA&&cameraUri!=null)getContentResolver().delete(cameraUri,null,null);cameraUri=null;return;}final String kind=pendingKind;pendingKind="";status.setText("Подготавливаем фото…");if(requestCode==REQUEST_CAMERA){if(cameraUri!=null){if(android.os.Build.VERSION.SDK_INT>=29){ContentValues ready=new ContentValues();ready.put(MediaStore.Images.Media.IS_PENDING,0);getContentResolver().update(cameraUri,ready,null,null);}uploadUri(kind,cameraUri,false);}else{Bitmap bitmap=data==null?null:(Bitmap)data.getParcelableExtra("data");if(bitmap==null){status.setText("Камера не передала фотографию. Попробуйте ещё раз");return;}uploadBitmap(kind,bitmap);}}else if(requestCode==REQUEST_GALLERY){cameraUri=null;Uri uri=data==null?null:data.getData();if(uri==null){status.setText("Фотография не выбрана");return;}try{int flags=data.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION;getContentResolver().takePersistableUriPermission(uri,flags);}catch(Exception ignored){}uploadUri(kind,uri,false);}}
 void uploadUri(String kind,Uri uri,boolean temporary){new Thread(()->{try{Bitmap bitmap=decodeScaledBitmap(uri);if(bitmap==null)throw new IllegalArgumentException();Bitmap preview=previewBitmap(bitmap);uploadPrepared(kind,compressBitmap(bitmap),preview);bitmap.recycle();}catch(OutOfMemoryError e){runOnUiThread(()->status.setText("Фото слишком большое. Выберите другое изображение"));}catch(Exception e){runOnUiThread(()->status.setText("Не удалось прочитать выбранное фото"));}finally{if(temporary)discardCameraFile();}}).start();}
 synchronized void discardCameraFile(){cameraUri=null;}
 void uploadBitmap(String kind,Bitmap bitmap){new Thread(()->{try{uploadPrepared(kind,compressBitmap(bitmap),previewBitmap(bitmap));}catch(Exception e){runOnUiThread(()->status.setText("Не удалось подготовить фото"));}}).start();}
 Bitmap decodeScaledBitmap(Uri uri)throws Exception{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;try(InputStream input=getContentResolver().openInputStream(uri)){if(input==null)throw new IllegalArgumentException();BitmapFactory.decodeStream(input,null,bounds);}if(bounds.outWidth<=0||bounds.outHeight<=0)throw new IllegalArgumentException();int sample=1;while(bounds.outWidth/sample>MAX_IMAGE_SIDE*2||bounds.outHeight/sample>MAX_IMAGE_SIDE*2)sample*=2;BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=sample;options.inPreferredConfig=Bitmap.Config.ARGB_8888;try(InputStream input=getContentResolver().openInputStream(uri)){if(input==null)throw new IllegalArgumentException();return BitmapFactory.decodeStream(input,null,options);}}
 byte[] compressBitmap(Bitmap original)throws Exception{int width=original.getWidth(),height=original.getHeight();float scale=Math.min(1f,(float)MAX_IMAGE_SIDE/Math.max(width,height));Bitmap prepared=original;if(scale<1f)prepared=Bitmap.createScaledBitmap(original,Math.round(width*scale),Math.round(height*scale),true);try(ByteArrayOutputStream output=new ByteArrayOutputStream()){if(!prepared.compress(Bitmap.CompressFormat.JPEG,82,output))throw new IllegalStateException();return output.toByteArray();}finally{if(prepared!=original)prepared.recycle();}}
 Bitmap previewBitmap(Bitmap source){int width=source.getWidth(),height=source.getHeight();float scale=Math.min(1f,320f/Math.max(width,height));Bitmap result=Bitmap.createScaledBitmap(source,Math.max(1,Math.round(width*scale)),Math.max(1,Math.round(height*scale)),true);return result==source?source.copy(Bitmap.Config.ARGB_8888,false):result;}
 void uploadPrepared(String kind,byte[] bytes,Bitmap preview)throws Exception{String b64=Base64.encodeToString(bytes,Base64.NO_WRAP);runOnUiThread(()->status.setText("Загружаем фото…"));JSONObject request=new JSONObject().put("kind",kind).put("data",b64);if(!registrationUploadToken.isEmpty())request.put("upload_token",registrationUploadToken);JSONObject response=ApiClient.post("/api/mobile_registration_upload.php",request);if(response.optBoolean("ok")){registrationUploadToken=response.optString("upload_token",registrationUploadToken);docs.put(kind,kind);runOnUiThread(()->{Button button=photoButtons.get(kind);ImageView image=photoPreviews.get(kind);if(button!=null&&!button.getText().toString().startsWith("✓"))button.setText("✓ "+button.getText().toString().substring(2));if(image!=null){image.setImageBitmap(preview);image.setVisibility(android.view.View.VISIBLE);}status.setText("Фото сохранено на сервере: "+docs.size()+" / 9");});}else{preview.recycle();runOnUiThread(()->status.setText(response.optString("error","Ошибка загрузки")));}}
 void submit(){if(type.equals("executor")&&docs.size()<9){status.setText("Сначала загрузите все фотографии и документы: "+docs.size()+" / 9");return;}status.setText("Отправляем данные…");new Thread(()->{try{JSONObject q=new JSONObject().put("type",type).put("name",s(name)).put("phone",s(phone)).put("email",s(email)).put("login",s(login)).put("password",s(pass));if(type.equals("executor")){JSONObject dj=new JSONObject();for(Map.Entry<String,String> e:docs.entrySet())dj.put(e.getKey(),e.getValue());JSONArray services=new JSONArray();for(Map.Entry<String,CheckBox> e:serviceChecks.entrySet())if(e.getValue().isChecked())services.put(e.getKey());q.put("vehicle_type",vehicle.getSelectedItemPosition()==0?"":vehicle.getSelectedItem().toString()).put("plate",s(plate)).put("capacity",s(capacity)).put("services",services).put("documents",dj).put("upload_token",registrationUploadToken).put("contract_accepted",contract!=null&&contract.isChecked());}if(type.equals("b2b"))q.put("company",s(company)).put("inn",s(inn)).put("contact",s(name));JSONObject r=ApiClient.post("/api/mobile_register.php",q);runOnUiThread(()->{if(r.optBoolean("ok")){String token=r.optString("token","");if(!token.isEmpty()){ApiClient.saveToken(this,token);startActivity(new Intent(this,DashboardActivity.class));finishAffinity();}else if("verification_required".equals(r.optString("status"))){Intent i=new Intent(this,VerificationActivity.class);i.putExtra("account_type",r.optString("account_type"));i.putExtra("id",r.optString("id"));i.putExtra("verification_token",r.optString("verification_token"));startActivity(i);finish();}else status.setText(r.optString("message","Регистрация отправлена")+"\nID: "+r.optString("id",""));}else status.setText(r.optString("error","Ошибка регистрации"));});}catch(Exception e){runOnUiThread(()->status.setText("Нет связи с AV Rescue"));}}).start();}
}
